node ToggleFF(btn, reset: bool) returns (q: bool);
var
  press: bool;
let
  press = RisingEdge(btn);
  q = false -> (if reset then false else if press then not pre(q) else pre(q));
tel

-- 4-Tap FIR Moving-Average and First-Order IIR Low-Pass Sensor Filter
const
  ALPHA: real = 0.25;

node MovingAverage4(x: real) returns (y_fir, y_iir: real);
var
  d1, d2, d3: real;
let
  d1 = x -> pre(x);
  d2 = x -> pre(d1);
  d3 = x -> pre(d2);
  y_fir = 0.25 * (x + d1 + d2 + d3);
  y_iir = x -> (ALPHA * x + (1.0 - ALPHA) * pre(y_iir));
tel

-- Automotive Cruise Control Mode Logic with Brake Safety Override
const
  MIN_SPEED: real = 30.0;
  MAX_SPEED: real = 140.0;
  KP: real = 0.8;

function Clamp(val, lo, hi: real) returns (out_v: real);
let
  out_v = if val < lo then lo else if val > hi then hi else val;
tel

node CruiseControl(on_cmd, off_cmd, brake: bool; speed, target_speed: real)
returns (engaged: bool; throttle: real);
var
  speed_ok: bool;
  err: real;
let
  speed_ok = (speed >= MIN_SPEED) and (speed <= MAX_SPEED);
  engaged = false -> (if brake or off_cmd or not speed_ok then false
                      else if on_cmd then true
                      else pre(engaged));
  err = target_speed - speed;
  throttle = if engaged then Clamp(KP * err, 0.0, 100.0) else 0.0;
  assert speed >= 0.0;
tel

-- Aircraft Landing Gear Door Sequencer with Synchronous Clock Partitioning
node LandingGearSequencer(handle_down, door_open, gear_locked, hyd_ok: bool)
returns (open_door_cmd, extend_gear_cmd: bool; active_ticks: int);
var
  extend_phase: bool;
  inc_ticks: int when hyd_ok;
  hold_ticks: int when not hyd_ok;
let
  extend_phase = handle_down and hyd_ok;
  open_door_cmd = extend_phase and not gear_locked;
  extend_gear_cmd = extend_phase and door_open and not gear_locked;

  inc_ticks = (1 -> (pre(active_ticks) + 1)) when hyd_ok;
  hold_ticks = (0 -> pre(active_ticks)) when not hyd_ok;
  active_ticks = merge hyd_ok (inc_ticks) (hold_ticks);

  assert not (extend_gear_cmd and not door_open);
tel

-- Dual-Channel Redundant Flight Control Voter with Discrepancy Persistence
const
  MAX_DIFF: real = 0.05;
  FAULT_LIMIT: int = 3;

function AbsDiff(a, b: real) returns (d: real);
let
  d = if a >= b then a - b else b - a;
tel

node FlightControlVoter(ch_a, ch_b: real; valid_a, valid_b: bool)
returns (cmd_out: real; fault_latched: bool; mismatch_cnt: int);
var
  disagree: bool;
  both_valid: bool;
let
  both_valid = valid_a and valid_b;
  disagree = both_valid and (AbsDiff(ch_a, ch_b) > MAX_DIFF);
  mismatch_cnt = 0 -> (if disagree then pre(mismatch_cnt) + 1 else 0);
  fault_latched = false -> (pre(fault_latched) or (mismatch_cnt >= FAULT_LIMIT));
  cmd_out = if fault_latched then 0.0
            else if both_valid then 0.5 * (ch_a + ch_b)
            else if valid_a then ch_a
            else if valid_b then ch_b
            else 0.0;
  assert mismatch_cnt >= 0;
tel

